for kind in ['high','low']:lines.append(f'| {kind} | {extra["before"][kind]["rear"]["rear_depth_laplacian_per_mm"]["rms"]:.6f} | {extra["after"][kind]["rear"]["rear_depth_laplacian_per_mm"]["rms"]:.6f} |')
